import {
  ChangeDetectionStrategy,
  Component,
  Injector,
  OnInit,
  effect,
  inject,
  input,
  signal,
} from '@angular/core';
import { FieldTree, FormField, FormRoot, form } from '@angular/forms/signals';
import { Router } from '@angular/router';
import { WizardStorage } from '../../core/storage/wizard-storage';
import { FormFieldConfig, SECTIONS, Section } from '../../domain/form/form-config';
import { buildStep1Schema } from './step1-schema';
import { reconcileStep1 } from './validation/reconcile-step1';
import {
  Step1Model,
  Step1RuleContext,
  isEffectivelyRequired,
  normalizeStep1Values,
} from './validation/step1-model';

/** Everything the form needs, already checked by the page (texts present, form `ready`). */
export interface Step1FormView {
  readonly countryCode: string;
  /** Valid fields in display order. */
  readonly fields: readonly FormFieldConfig[];
  readonly legends: Readonly<Record<Section, string>>;
  readonly continueLabel: string;
  readonly genericErrorMessage: string;
  readonly ruleContext: Step1RuleContext;
}

interface SectionView {
  readonly id: Section;
  readonly legend: string;
  readonly fields: readonly FormFieldConfig[];
}

/**
 * Dynamic form of step 1 (ADR-0002): flat model indexed by key, schema generated from the
 * configuration, native controls bound with `[formField]`, accessibility attributes bound by hand
 * (the spike showed `FormField` does not set `aria-invalid` nor `aria-describedby`).
 *
 * The configuration is immutable for the life of the component: a reload recreates it.
 */
@Component({
  selector: 'app-dynamic-form',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormRoot, FormField],
  templateUrl: './dynamic-form.html',
  styleUrl: './dynamic-form.css',
})
export class DynamicForm implements OnInit {
  readonly view = input.required<Step1FormView>();

  private readonly injector = inject(Injector);
  private readonly storage = inject(WizardStorage);
  private readonly router = inject(Router);

  private readonly model = signal<Step1Model>({});
  /** Created in `ngOnInit`, once the input is available (ADR-0002). */
  protected f!: FieldTree<Step1Model>;
  protected sections: readonly SectionView[] = [];

  ngOnInit(): void {
    const view = this.view();
    const reconciled = reconcileStep1(view.fields, this.storage.readStep1(view.countryCode));
    for (const warning of reconciled.warnings) {
      console.warn(warning);
    }
    // Initialised with the reconciled values, so the first write below is idempotent (ADR-0004).
    this.model.set(reconciled.values);

    this.sections = SECTIONS.map((id) => ({
      id,
      legend: view.legends[id],
      fields: view.fields.filter((field) => field.section === id),
    })).filter((section) => section.fields.length > 0);

    this.f = form(this.model, buildStep1Schema(view.fields, view.ruleContext), {
      injector: this.injector,
      submission: {
        action: async () => {
          this.persist();
          await this.router.navigate(['/', view.countryCode, 'plans']);
          return undefined;
        },
        onInvalid: () => this.focusFirstInvalid(),
      },
    });

    // REQ-01.23: every change of value is stored, normalised, for this country only.
    effect(() => this.persist(this.model()), { injector: this.injector });
  }

  // Typed accessors: the field type fixes the value type (initialValue / reconcileStep1). The
  // cast is the "deliberate escape hatch" of the dynamic-forms guide (ADR-0002).
  protected asText(key: string): FieldTree<string> {
    return this.f[key] as unknown as FieldTree<string>;
  }

  protected asNumber(key: string): FieldTree<number | null> {
    return this.f[key] as unknown as FieldTree<number | null>;
  }

  protected asBoolean(key: string): FieldTree<boolean> {
    return this.f[key] as unknown as FieldTree<boolean>;
  }

  protected isRequired(field: FormFieldConfig): boolean {
    return isEffectivelyRequired(field);
  }

  /** REQ-01.16: after the first blur or the first attempt to continue, then live. */
  protected errorVisible(key: string): boolean {
    const state = this.f[key]();
    return state.touched() && state.invalid();
  }

  /** The single message of the field, or the generic one of the country (REQ-01.16). */
  protected errorMessage(field: FormFieldConfig): string {
    return field.errorMessage ?? this.view().genericErrorMessage;
  }

  protected describedBy(field: FormFieldConfig): string | null {
    const ids = [
      field.helpText ? `help-${field.key}` : null,
      this.errorVisible(field.key) ? `err-${field.key}` : null,
    ].filter((id): id is string => id !== null);
    return ids.length > 0 ? ids.join(' ') : null;
  }

  /** While typing the raw text is kept; on leaving the field it is replaced by the trimmed one. */
  protected trimText(key: string): void {
    const value = this.model()[key];
    if (typeof value === 'string' && value !== value.trim()) {
      this.model.update((model) => ({ ...model, [key]: value.trim() }));
    }
  }

  private persist(model: Step1Model = this.model()): void {
    const view = this.view();
    this.storage.writeStep1(view.countryCode, normalizeStep1Values(view.fields, model));
  }

  /** REQ-01.17: focus the first invalid field in display order (not `errorSummary()`). */
  private focusFirstInvalid(): void {
    const first = this.view().fields.find((field) => this.f[field.key]().invalid());
    if (first) {
      this.f[first.key]().focusBoundControl();
    }
  }
}
import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { CountryConfig } from '../../core/country/country-config';
import { CountryContext } from '../../core/country/country-context';
import { StatusMessage } from '../../shared/status-message';
import { StepHeading } from '../../shared/step-heading';
import { DynamicForm, Step1FormView } from './dynamic-form';
import { Step1ResultReader } from './validation/step1-result-reader';

/** What step 1 shows, derived from the configuration of the country (ADR-0004 `viewState`). */
export type FormStepState =
  | { readonly kind: 'configError'; readonly message: string }
  | { readonly kind: 'empty'; readonly title: string; readonly message: string }
  | { readonly kind: 'unavailable'; readonly title: string; readonly message: string }
  | { readonly kind: 'ready'; readonly title: string; readonly view: Step1FormView };

/**
 * Pure derivation of the state of step 1 (REQ-01.5, REQ-01.13, REQ-01.22):
 *
 * - A missing text of step 1 → generic error of the country instead of the form (AC-01.35).
 * - No valid field → empty-state message of the country, no continue (AC-01.9).
 * - A required role missing → generic error, no continue (AC-01.20).
 */
export function formStepState(
  config: CountryConfig,
  ruleContext: Step1FormView['ruleContext'],
): FormStepState {
  const formTexts = config.texts.formStep;
  const wizardTexts = config.texts.wizard;
  if (
    config.form.status === 'configError' ||
    formTexts.status !== 'ok' ||
    wizardTexts.status !== 'ok'
  ) {
    return { kind: 'configError', message: config.genericErrorMessage };
  }
  const title = formTexts.texts.title;
  switch (config.form.status) {
    case 'empty':
      return { kind: 'empty', title, message: formTexts.texts.emptyMessage };
    case 'unavailable':
      return { kind: 'unavailable', title, message: config.genericErrorMessage };
    case 'ready':
      return {
        kind: 'ready',
        title,
        view: {
          countryCode: config.country.code,
          fields: config.form.fields,
          legends: {
            policyholder: wizardTexts.texts.policyholderSectionLabel,
            vehicle: wizardTexts.texts.vehicleSectionLabel,
          },
          continueLabel: formTexts.texts.continueLabel,
          genericErrorMessage: config.genericErrorMessage,
          ruleContext,
        },
      };
  }
}

/**
 * Step 1, `/:country/form` (US-01). The shell shows "cargando" and "error de carga" while the
 * configuration is not ready (REQ-01.3, REQ-01.4), so this page always has a configuration.
 */
@Component({
  selector: 'app-form-step-page',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DynamicForm, StatusMessage, StepHeading],
  template: `
    @if (state(); as s) {
      @if (s.kind === 'configError') {
        <app-status-message kind="message" [message]="s.message" />
      } @else if (s.kind === 'ready') {
        <app-step-heading [text]="s.title" />
        <app-dynamic-form [view]="s.view" />
      } @else {
        <app-step-heading [text]="s.title" />
        <app-status-message kind="message" [message]="s.message" />
      }
    }
  `,
})
export class FormStepPage {
  private readonly context = inject(CountryContext);
  private readonly reader = inject(Step1ResultReader);

  protected readonly state = computed(() => {
    const config = this.context.config();
    return config ? formStepState(config, this.reader.ruleContext(config)) : null;
  });
}

@if (view(); as v) {
  @if (v.kind === 'configError') {
    <app-status-message kind="message" [message]="v.message" />
  } @else {
    <app-step-heading [text]="v.texts.title" />

    @if (v.kind === 'loading') {
      <app-status-message kind="loading" />
    } @else if (v.kind === 'error') {
      <app-status-message kind="error" (retry)="retry()" />
    } @else {
      @if (planUnavailable()) {
        <p class="notice" role="alert">{{ v.texts.planUnavailableMessage }}</p>
      }

      @if (v.kind === 'empty') {
        <app-status-message kind="message" [message]="v.texts.emptyMessage" />
        <div class="actions">
          <button type="button" (click)="back()">{{ v.texts.backLabel }}</button>
        </div>
      } @else {
        <form (submit)="onContinue($event)" novalidate>
          <fieldset
            class="plans-group"
            [attr.aria-describedby]="choosePlanShown() ? 'choose-plan-message' : null"
          >
            <legend>{{ v.texts.groupLegend }}</legend>

            <div class="plans">
              @for (item of v.plans; track item.plan.id) {
                <div
                  class="plan"
                  [class.plan--recommended]="item.highlighted"
                  [class.plan--selected]="selected() === item.plan.id"
                >
                  <input
                    type="radio"
                    name="plan"
                    [id]="'plan-' + item.plan.id"
                    [value]="item.plan.id"
                    [checked]="selected() === item.plan.id"
                    (change)="select(item.plan.id)"
                  />
                  <label class="plan-label" [for]="'plan-' + item.plan.id">
                    <!-- &ngsp; keeps a space between the parts of the accessible name (whitespace is removed). -->
                    <span class="plan-name">{{ item.plan.name }}</span>&ngsp;
                    @if (item.highlighted) {
                      <span class="badge">{{ v.texts.recommendedLabel }}</span>&ngsp;
                    }
                    <span class="plan-price">{{ item.formattedPrice }}</span>
                  </label>

                  @if (item.plan.shortDescription) {
                    <p class="plan-description">{{ item.plan.shortDescription }}</p>
                  }
                  @if (item.plan.coverages.length > 0) {
                    <p class="list-title" [id]="'coverages-' + item.plan.id">
                      {{ v.texts.coveragesHeading }}
                    </p>
                    <ul [attr.aria-labelledby]="'coverages-' + item.plan.id">
                      @for (coverage of item.plan.coverages; track $index) {
                        <li>{{ coverage }}</li>
                      }
                    </ul>
                  }
                  @if (item.plan.benefits.length > 0) {
                    <p class="list-title" [id]="'benefits-' + item.plan.id">
                      {{ v.texts.benefitsHeading }}
                    </p>
                    <ul [attr.aria-labelledby]="'benefits-' + item.plan.id">
                      @for (benefit of item.plan.benefits; track $index) {
                        <li>{{ benefit }}</li>
                      }
                    </ul>
                  }
                </div>
              }
            </div>

            @if (choosePlanShown()) {
              <p id="choose-plan-message" class="error" role="alert">
                {{ v.texts.choosePlanMessage }}
              </p>
            }
          </fieldset>

          <div class="actions">
            <button type="button" (click)="back()">{{ v.texts.backLabel }}</button>
            <button type="submit">{{ v.texts.continueLabel }}</button>
          </div>
        </form>
      }
    }
  }
}
@if (title(); as pageTitle) {
  <app-step-heading [text]="pageTitle" />

  <div class="summary">
    <!-- Data of step 1 (REQ-03.1 to REQ-03.3, REQ-03.6) -->
    <section class="summary-section summary-data">
      @if (dataTexts(); as texts) {
        @for (section of sections(); track section.id) {
          <h2 [id]="'summary-' + section.id">{{ section.legend }}</h2>
          <dl [attr.aria-labelledby]="'summary-' + section.id">
            @for (item of section.items; track item.key) {
              <div class="item">
                <dt>{{ item.label }}</dt>
                <dd>{{ item.display }}</dd>
              </div>
            }
          </dl>
        }
        <button type="button" (click)="editData()" [disabled]="processing()">
          {{ texts.editDataLabel }}
        </button>
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Chosen plan and final price (REQ-03.4, REQ-03.5) -->
    <section class="summary-section summary-plan" aria-labelledby="summary-plan-heading">
      @if (planTexts(); as texts) {
        <h2 id="summary-plan-heading">{{ texts.planHeading }}</h2>
        @if (planState(); as state) {
          @if (state.kind === 'loading') {
            <app-status-message kind="loading" />
          } @else if (state.kind === 'error') {
            <app-status-message kind="error" (retry)="planResource.reload()" />
          } @else {
            <p class="plan-name">{{ state.plan.plan.name }}</p>
            @if (state.plan.plan.shortDescription) {
              <p>{{ state.plan.plan.shortDescription }}</p>
            }
            @if (state.plan.plan.coverages.length > 0) {
              <p class="list-title" id="summary-coverages">{{ texts.coveragesHeading }}</p>
              <ul aria-labelledby="summary-coverages">
                @for (coverage of state.plan.plan.coverages; track $index) {
                  <li>{{ coverage }}</li>
                }
              </ul>
            }
            @if (state.plan.plan.benefits.length > 0) {
              <p class="list-title" id="summary-benefits">{{ texts.benefitsHeading }}</p>
              <ul aria-labelledby="summary-benefits">
                @for (benefit of state.plan.plan.benefits; track $index) {
                  <li>{{ benefit }}</li>
                }
              </ul>
            }
            <p class="final-price">
              <span>{{ texts.finalPriceLabel }}</span>&ngsp;
              <strong>{{ state.plan.formattedPrice }}</strong>
            </p>
          }
        }
        <button type="button" (click)="changePlan()" [disabled]="processing()">
          {{ texts.changePlanLabel }}
        </button>
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Terms and conditions (REQ-03.15 to REQ-03.18) -->
    <section class="summary-section summary-terms" aria-labelledby="summary-terms-heading">
      @if (termsTexts(); as texts) {
        <h2 id="summary-terms-heading">{{ texts.termsHeading }}</h2>
        @if (termsState(); as state) {
          @if (state.kind === 'loading') {
            <app-status-message kind="loading" />
          } @else if (state.kind === 'error') {
            <app-status-message kind="error" (retry)="termsResource.reload()" />
          } @else if (state.kind === 'unavailable') {
            <app-status-message kind="message" [message]="texts.termsUnavailableMessage" />
          } @else {
            <div
              class="terms-region"
              role="region"
              tabindex="0"
              aria-labelledby="summary-terms-heading"
            >
              <app-terms-blocks [document]="state.document" />
            </div>
          }
          <div class="accept">
            <input
              type="checkbox"
              id="accept-terms"
              [checked]="termsAccepted()"
              [disabled]="state.kind !== 'ready' || processing()"
              (change)="onTermsChange($event)"
            />
            <label for="accept-terms">{{ texts.acceptTermsLabel }}</label>
          </div>
        }
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Simulated gateway and payment (REQ-03.19 to REQ-03.25, REQ-03.30, REQ-03.35) -->
    <section class="summary-section summary-payment">
      @if (paymentTexts(); as texts) {
        <fieldset class="gateway">
          <legend>{{ texts.gatewayLegend }}</legend>
          <div class="outcome">
            <input
              type="radio"
              name="payment-outcome"
              id="outcome-approved"
              value="approved"
              [checked]="outcome() === 'approved'"
              [disabled]="processing()"
              (change)="chooseOutcome('approved')"
            />
            <label for="outcome-approved">{{ texts.approvedOptionLabel }}</label>
          </div>
          <div class="outcome">
            <input
              type="radio"
              name="payment-outcome"
              id="outcome-rejected"
              value="rejected"
              [checked]="outcome() === 'rejected'"
              [disabled]="processing()"
              (change)="chooseOutcome('rejected')"
            />
            <label for="outcome-rejected">{{ texts.rejectedOptionLabel }}</label>
          </div>
        </fieldset>

        @if (!termsAccepted() && termsTexts(); as hintTexts) {
          <p id="pay-hint" class="hint">{{ hintTexts.acceptTermsHint }}</p>
        }
        <button
          type="button"
          class="pay"
          [disabled]="payNativelyDisabled()"
          [attr.aria-disabled]="processing() ? 'true' : null"
          [attr.aria-busy]="processing() ? 'true' : null"
          [attr.aria-describedby]="payDescribedBy()"
          (click)="pay()"
        >
          {{ texts.payLabel }}
        </button>
        <p id="pay-status" class="processing" aria-live="polite">
          @if (processing()) {
            {{ texts.processingMessage }}
          }
        </p>
        @if (payment() === 'rejected') {
          <p id="pay-rejected" class="rejected" role="alert">{{ texts.rejectedMessage }}</p>
        }
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>
  </div>
} @else {
  <app-status-message kind="message" [message]="genericErrorMessage()" />
}

