      modifyRealResponse(route, (body) => {
        (body.data as unknown[]).push({
          id: 9400,
          documentId: 'e2eoptional0000000000001',
          key: 'co_nickname',
          label: 'Apodo',
          type: 'text',
          required: false,
          helpText: null,
          errorMessage: null,
          order: 7,
          section: 'policyholder',
          role: null,
          options: [],
          validations: [],
        });
      }),
    );
